-- Finance seed (generated by build_finance_seed.py) — Phase 0.
-- Idempotent for a fresh finance schema. Safe to re-run before app writes exist.
-- pnl history keeps app-written rows (delete only source='import').

begin;

delete from finance_pnl_monthly where source = 'import';
on conflict (year, month, line_item) do update set value = excluded.value, state = excluded.state, source = excluded.source, updated_at = now();

delete from finance_client_monthly;
on conflict (year, month, client_canon, sub_account) do nothing;

delete from client_rates;

delete from finance_events;

delete from fx_rates;
on conflict (year, month) do update set usd_ils = excluded.usd_ils;

commit;
